TLM.f("Tempora/Pent18-4",{"officium":"Feria Quinta infra Hebdomadam XVIII post Octavam Pentecostes","rule":["Oratio Dominica","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"ruleInherited":["Gloria","Credo","Prefatio=Trinitate","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"fallback":"Tempora/Pent18-0","from":{"Introitus":"Tempora/Pent18-0","Oratio":"Tempora/Pent18-0","Lectio":"Tempora/Pent18-0","Graduale":"Tempora/Pent18-0","Evangelium":"Tempora/Pent18-0","Offertorium":"Tempora/Pent18-0","Secreta":"Tempora/Pent18-0","Communio":"Tempora/Pent18-0","Postcommunio":"Tempora/Pent18-0"},"sections":{"Introitus":[{"k":"ref","la":"Eccli 36:18"},{"k":"text","la":"Da pacem, Dómine, sustinéntibus te, ut prophétæ tui fidéles inveniántur: exáudi preces servi tui et plebis tuæ Israël"},{"k":"ref","la":"Ps 121:1"},{"k":"text","la":"Lætátus sum in his, quæ dicta sunt mihi: in domum Dómini íbimus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Da pacem, Dómine, sustinéntibus te, ut prophétæ tui fidéles inveniántur: exáudi preces servi tui et plebis tuæ Israël"}],"Oratio":[{"k":"text","la":"Dírigat corda nostra, quǽsumus, Dómine, tuæ miseratiónis operátio: quia tibi sine te placére non póssumus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corinthios"},{"k":"ref","la":"1 Cor 1:4-8"},{"k":"text","la":"Fratres: Grátias ago Deo meo semper pro vobis in grátia Dei, quæ data est vobis in Christo Jesu: quod in ómnibus dívites facti estis in illo, in omni verbo et in omni sciéntia: sicut testimónium Christi confirmátum est in vobis: ita ut nihil vobis desit in ulla grátia, exspectántibus revelatiónem Dómini nostri Jesu Christi, qui et confirmábit vos usque in finem sine crímine, in die advéntus Dómini nostri Jesu Christi."}],"Graduale":[{"k":"ref","la":"Ps 121:1; 121:7"},{"k":"text","la":"Lætátus sum in his, quæ dicta sunt mihi: in domum Dómini íbimus."},{"k":"text","la":"Fiat pax in virtúte tua: et abundántia in túrribus tuis. Allelúja, allelúja","mark":"V"},{"k":"ref","la":"Ps 101:16"},{"k":"text","la":"Timébunt gentes nomen tuum, Dómine, et omnes reges terræ glóriam tuam. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 9:1-8"},{"k":"text","la":"In illo témpore: Ascéndens Jesus in navículam, transfretávit et venit in civitátem suam. Et ecce, offerébant ei paralýticum jacéntem in lecto. Et videns Jesus fidem illórum, dixit paralýtico: Confíde, fili, remittúntur tibi peccáta tua. Et ecce, quidam de scribis dixérunt intra se: Hic blasphémat. Et cum vidísset Jesus cogitatiónes eórum, dixit: Ut quid cogitátis mala in córdibus vestris? Quid est facílius dícere: Dimittúntur tibi peccáta tua; an dícere: Surge et ámbula? Ut autem sciátis, quia Fílius hóminis habet potestátem in terra dimitténdi peccáta, tunc ait paralýtico: Surge, tolle lectum tuum, et vade in domum tuam. Et surréxit et ábiit in domum suam. Vidéntes autem turbæ timuérunt, et glorificavérunt Deum, qui dedit potestátem talem homínibus."}],"Offertorium":[{"k":"ref","la":"Exodi 24:4; 24:5"},{"k":"text","la":"Sanctificávit Móyses altáre Dómino, ófferens super illud holocáusta et ímmolans víctimas: fecit sacrifícium vespertínum in odórem suavitátis Dómino Deo, in conspéctu filiórum Israël."}],"Secreta":[{"k":"text","la":"Deus, qui nos, per hujus sacrifícii veneránda commércia, uníus summæ divinitátis partícipes éfficis: præsta, quǽsumus; ut, sicut tuam cognóscimus veritátem, sic eam dignis móribus assequámur."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 95:8-9"},{"k":"text","la":"Tóllite hóstias, et introíte in átria ejus: adoráte Dóminum in aula sancta ejus."}],"Postcommunio":[{"k":"text","la":"Grátias tibi reférimus, Dómine, sacro múnere vegetáti: tuam misericórdiam deprecántes; ut dignos nos ejus participatióne perfícias."},{"k":"macro","name":"Per Dominum"}]},"hr":{"86ab7e445a57e34a":{"t":"Sir 36, 18, Ps 121, 1\n(Sir 36, 18) Daj mir, Gospodine, onima koji te čekaju, da se tvoji proroci pokažu pouzdani! Usliši molbe svoga sluge i puka svoga Izraela. (Ps 121, 1) Obradovah se kad mi rekoše: Idemo u dom Gospodnji.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sir 36, 18) Daj mir, Gospodine, onima koji te čekaju, da se tvoji proroci pokažu pouzdani! Usliši molbe svoga sluge i puka svoga Izraela."},"442d53ee7c529926":{"t":"<i>Pomolimo se</i>.\nNašim srcima, molimo, Gospodine, neka upravlja djelovanje tvoga milosrđa, jer se tebi bez tebe ne možemo svidjeti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"3b736abb2ebfa0d2":{"t":"1 Kor 1, 4-8\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo, neprestano za vas zahvaljujem svojem Bogu na njegovoj milosti, koja vam je dana u Kristu Isusu. Po njemu ste bogati u svemu, u svakoj riječi i u svakom znanju. Otkad se među vama učvrstilo propovijedanje Kristova evanđelja, imate sve milosti. I čekate da se pojavi naš Gospodin Isus Krist, koji će vas učiniti postojanima do kraja, da budete bez krivice na dan dolaska našega Gospodina Isusa Krista."},"58789cf2b2fdefdb":{"t":"Ps 121, 1 i 7\nObradovah se kad mi rekoše: Idemo u dom Gospodnji. Neka bude mir u zidinama tvojim, sigurnost u palačama tvojim.\n\nPs 101, 16\n<i>Aleluja</i>, <i>aleluja</i>.\nNarodi će se bojati imena tvojega, Gospodine, i svi zemaljski kraljevi slave tvoje. <i>Aleluja</i>."},"805b736b5e10e909":{"t":"Mt 9, 1-8\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme uđe Isus u lađu, preplovi jezero i dođe u svoj grad. I gle, donesu pred njega uzetoga koji je ležao na postelji. Kad je Isus vidio njihovu vjeru, reče uzetomu: Uzdaj se, sinko, opraštaju ti se tvoji grijesi! Neki od književnika pomisle u sebi: Ovaj huli. A Isus, znajući njihove misli, reče im: Zašto mislite zlo u svojim srcima? Što je lakše reći: Opraštaju ti se tvoji grijesi, ili: Ustani i hodi? A da znate da Sin Čovječji ima vlast na zemlji opraštati grijehe, reče uzetomu: Ustani, uzmi svoju postelju i pođi svojoj kući! I on ustade i pođe svojoj kući. Kad su ljudi to vidjeli, pobojali su se i slavili su Boga, koji je dao takvu moć ljudima."},"992f2c66e569773c":{"t":"Izl 24, 4 i 5\nPosvetio je Mojsije žrtvenik Gospodinu prinijevši na njemu paljenice i žrtvujući žrtve. Prikazao je večernju žrtvu kao ugodni miris Gospodinu naočigled sinova Izraelovih."},"12243debf46b9686":{"t":"Bože, koji nas po časnoj zamjeni u ovoj žrtvi činiš dionicima višnje naravi jedinoga Boga, podaj, molimo, kao što upoznajemo tvoju istinu da je tako i postignemo dostojnim djelima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"f45485c913aa2d68":{"t":"Ps 95, 8-9\nPrinesite žrtve i uđite u dvore njegove, klanjajte se Gospodinu u svetom hramu njegovu."},"84af45144709fee8":{"t":"<i>Pomolimo se</i>.\nOkrijepljeni svetim darom zahvaljujemo ti, Gospodine, i molimo tvoje milosrđe da nas učiniš dostojnima toga dara.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
